  0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
  0xF0, 0x80, 0x80, 0x80, 0xF0, // C
  0xE0, 0x90, 0x90, 0x90, 0xE0, // D
  0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
  0xF0, 0x80, 0xF0, 0x80, 0x80  // F
];

const CHIP8 = {
  memory: new Uint8Array(4096),
  V: new Uint8Array(16),
  I: 0,
  pc: 0x200,
  stack: new Uint16Array(16),
  sp: 0,
  delayTimer: 0,
  soundTimer: 0,
  k: new Uint8Array(16),
  display: new Uint8Array(64 * 32),
  running: false,
  insPerFrame: 10,
  lastROMName: "built-in demo"
};

const canvas = document.getElementById("screen");
const ctx = canvas.getContext("2d");
const img = ctx.createImageData(64, 32);

function loadFont() {
  for (let i = 0; i < FONT.length; i++) CHIP8.memory[0x50 + i] = FONT[i];
}

function reset() {
  const mem = CHIP8.memory;
  const keepProgram = true; // preserve ROM
  if (!keepProgram) mem.fill(0);
  CHIP8.V.fill(0);
  CHIP8.I = 0;
  CHIP8.pc = 0x200;
  CHIP8.sp = 0;
  CHIP8.delayTimer = 0;
  CHIP8.soundTimer = 0;
  CHIP8.k.fill(0);
  CHIP8.display.fill(0);
  loadFont();
  render();
  updateDebugger();
}

function loadROM(bytes, name) {
  // Clear program area (keep font)
  for (let i = 0x200; i < 4096; i++) CHIP8.memory[i] = 0;
  const len = Math.min(bytes.length, 0x1000 - 0x200);
  for (let i = 0; i < len; i++) CHIP8.memory[0x200 + i] = bytes[i] & 0xFF;
  CHIP8.lastROMName = name;
  document.getElementById("rom-name").textContent = name;
  reset();
}

/* ---------- Instruction decode ---------- */

function decode(ins) {
  // returns {mnemonic, op1, op2, detail} for debugger
  const kk = ins & 0x000F;
  const n = (ins >> 8) & 0x000F;
  const x = (ins >> 8) & 0x000F;
  const y = (ins >> 4) & 0x000F;
  const xx = (ins >> 8) & 0x000F;
  const nnn = ins & 0x0FFF;
  const nnnn = ins & 0x0FFF;
  const nn = (ins >> 8) & 0x00FF;

  switch (ins & 0xF000) {
    case 0x0000:
      if (ins === 0x00E0) return ["CLS", "", "Clear screen"];
      if (ins === 0x00EE) return ["RET", "", "Return from subroutine"];
      if ((ins & 0x00F0) === 0x00D0) return ["SYS", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "No-op (SYS)"];
      if ((ins & 0x00F0) === 0x00AN) {
        const nn2 = (ins >> 8) & 0x00FF;
        return ["LD I", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "Set I (old-style)"];
      }
      return ["?", "0x" + ins.toString(16).padStart(4, "0"), "Unknown 0x0NNN"];
    case 0x1000:
      return ["JP", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "Jump to address"];
    case 0x2000:
      return ["CALL", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "Call subroutine"];
    case 0x3000:
      return ["SE V" + x, "0x" + nn.toString(16).padStart(2, "0"), "Skip if V[x] == n"];
    case 0x4000:
      return ["SNE V" + x, "0x" + nn.toString(16).padStart(2, "0"), "Skip if V[x] != n"];
    case 0x5000:
      return ["SE V" + x, "V" + y, "Skip if V[x] == V[y]"];
    case 0x6000:
      return ["LD V" + x, "0x" + nn.toString(16).padStart(2, "0"), "Set V[x] = n"];
    case 0x7000:
      return ["ADD V" + x, "0x" + nn.toString(16).padStart(2, "0"), "V[x] += n (no carry)"];
    case 0x8000:
      switch (kk) {
        case 0x0: return ["LD V" + x, "V" + y, "V[x] = V[y]"];
        case 0x1: return ["OR  V" + x, "V" + y, "V[x] |= V[y]"];
        case 0x2: return ["AND V" + x, "V" + y, "V[x] &= V[y]"];
        case 0x3: return ["XOR V" + x, "V" + y, "V[x] ^= V[y]"];
        case 0x4: return ["ADD V" + x, "V" + y, "V[x] += V[y], VF=carry"];
        case 0x5: return ["SUB V" + x, "V" + y, "V[x] -= V[y], VF=not borrow"];
        case 0x6: return ["SHR V" + x, "", "V[x] >>= 1, VF=LSB"];
        case 0x7: return ["SUBN V" + x, "V" + y", "V[x] = V[y] - V[x], VF=not borrow"];
        case 0xE: return ["SHL V" + x, "", "V[x] <<= 1, VF=MSB (ext.)"];
        default: return ["?", "0x" + ins.toString(16).padStart(4, "0"), "Unknown 8NNK"];
      }
    case 0x9000:
      return ["SNE V" + x, "V" + y, "Skip if V[x] != V[y]"];
    case 0xA000:
      return ["LD I", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "Set I = address"];
    case 0xB000:
      return ["JP V0", "0x" + (ins & 0x0FFF).toString(16).padStart(4, "0"), "Jump to address + V[0]"];
    case 0xC000:
      return ["RND V" + x, "0x" + nn.toString(16).padStart(2, "0"), "V[x] = random & n"];
    case 0xD000:
      return ["DRW V" + x, "V" + y, x + " bytes @ (V[x],V[y])"];
    case 0xE000:
      if ((ins & 0x00FF) === 0x009E) return ["SKP V" + x, "", "Skip if V[x] pressed"];
      if ((ins & 0x00FF) === 0x00A1) return ["SKNP V" + x, "", "Skip if V[x] not pressed"];
      return ["?", "0x" + ins.toString(16).padStart(4, "0"), "Unknown ENN"];
    case 0xF000:
      switch ((ins >> 8) & 0x00FF) {
        case 0x00: return ["LD V" + x, "DT", "V[x] = delay timer"];
        case 0x01: return ["LD DT", "V" + x, "delay timer = V[x]"];
        case 0x0A: return ["LD V" + x, "KEY", "Wait for key → V[x]"];
        case 0x02: return ["LD ST", "V" + x, "sound timer = V[x]"];
        case 0x15: return ["LD V" + x, "I", "V[x] = I"];
        case 0x18: return ["LD I", "V" + x, "I = V[x]"];
        case 0x1E: return ["LD I", "+V" + x, "I += V[x]"];
        case 0x29: return ["LD F", "V" + x, "I = font sprite of V[x]"];
        case 0x33: return ["BCD V" + x, "", "Store BCD of V[x] at I"];
        case 0x55: return ["LD [I]", "V0..V" + x, "Store V[0..x] at I"];
        case 0x65: return ["LD V0..V" + x, "[I]", "Load V[0..x] from I"];
        default: return ["?", "0x" + ins.toString(16).padStart(4, "0"), "Unknown FNN"];
      }
  }
  return ["?", "0x" + ins.toString(16).padStart(4, "0"), "Unknown"];
}

/* ---------- Sprite drawing ---------- */

function drawSprite(x, y, n, setCollisionFlag) {
  let collision = false;
  x = ((x % 64) + 64) % 64;
  const baseY = y;
  for (let row = 0; row < n; row++) {
    const byte = CHIP8.memory[CHIP8.I + row];
    const yy = (baseY + row) % 32;
    for (let col = 0; col < 8; col++) {
      const bit = (byte >> (7 - col)) & 1;
      if (bit) {
        const xx = (x + col) % 64;
        const idx = yy * 64 + xx;
        if (CHIP8.display[idx]) collision = true;
        CHIP8.display[idx] ^= 1;
      }
    }
  }
  if (setCollisionFlag) CHIP8.V[0xF] = collision ? 1 : 0;
}

/* ---------- Execute one instruction ---------- */

function step() {
  const mem = CHIP8.memory;
  const pc = CHIP8.pc;
  const ins = ((mem[pc] << 8) | mem[pc + 1]) & 0xFFFF;
  CHIP8.pc = pc + 2;

  const x = (ins >> 8) & 0x000F;
  const y = (ins >> 4) & 0x000F;
  const nn = (ins >> 8) & 0x00FF;
  const nnn = ins & 0x0FFF;
  const kk = ins & 0x000F;

  switch (ins & 0xF000) {
    case 0x0000:
      if (ins === 0x00E0) {
        CHIP8.display.fill(0);
      } else if (ins === 0x00EE) {
        if (CHIP8.sp === 0) return;
        CHIP8.sp--;
        CHIP8.pc = CHIP8.stack[CHIP8.sp];
      } else if ((ins & 0x00F0) === 0x00D0) {
        // SYS — no-op on modern interpreters
      } else if ((ins & 0x00F0) === 0x00A0) {
        CHIP8.I = ins & 0x0FFF;
      }
      break;

    case 0x1000:
      CHIP8.pc = nnn;
      break;

    case 0x2000:
      if (CHIP8.sp >= 16) return;
      CHIP8.stack[CHIP8.sp] = CHIP8.pc;
      CHIP8.sp++;
      CHIP8.pc = nnn;
      break;

    case 0x3000:
      if (CHIP8.V[x] === nn) CHIP8.pc += 2;
      break;

    case 0x4000:
      if (CHIP8.V[x] !== nn) CHIP8.pc += 2;
      break;

    case 0x5000:
      if (CHIP8.V[x] === CHIP8.V[y]) CHIP8.pc += 2;
      break;

    case 0x6000:
      CHIP8.V[x] = nn;
      break;

    case 0x7000:
      CHIP8.V[x] = (CHIP8.V[x] + nn) & 0xFF;
      break;

    case 0x8000:
      switch (kk) {
        case 0x0: CHIP8.V[x] = CHIP8.V[y]; break;
        case 0x1: CHIP8.V[x] = (CHIP8.V[x] | CHIP8.V[y]) & 0xFF; break;
        case 0x2: CHIP8.V[x] = (CHIP8.V[x] & CHIP8.V[y]) & 0xFF; break;
        case 0x3: CHIP8.V[x] = (CHIP8.V[x] ^ CHIP8.V[y]) & 0xFF; break;
        case 0x4: {
          const sum = CHIP8.V[x] + CHIP8.V[y];
          CHIP8.V[x] = sum & 0xFF;
          CHIP8.V[0xF] = sum > 0xFF ? 1 : 0;
          break;
        }
        case 0x5: {
          const noBorrow = CHIP8.V[x] >= CHIP8.V[y];
          CHIP8.V[x] = (CHIP8.V[x] - CHIP8.V[y]) & 0xFF;
          CHIP8.V[0xF] = noBorrow ? 1 : 0;
          break;
        }
        case 0x6: {
          CHIP8.V[0xF] = CHIP8.V[x] & 1;
          CHIP8.V[x] = CHIP8.V[x] >> 1;
          break;
        }
        case 0x7: {
          const noBorrow = CHIP8.V[y] >= CHIP8.V[x];
          CHIP8.V[x] = (CHIP8.V[y] - CHIP8.V[x]) & 0xFF;
          CHIP8.V[0xF] = noBorrow ? 1 : 0;
          break;
        }
        case 0xE: {
          CHIP8.V[0xF] = (CHIP8.V[x] >> 7) & 1;
          CHIP8.V[x] = (CHIP8.V[x] << 1) & 0xFF;
          break;
        }
      }
      break;

    case 0x9000:
      if (CHIP8.V[x] !== CHIP8.V[y]) CHIP8.pc += 2;
      break;

    case 0xA000:
      CHIP8.I = nnn;
      break;

    case 0xB000:
      CHIP8.pc = (nnn + CHIP8.V[0]) & 0xFFFF;
      break;

    case 0xC000:
      CHIP8.V[x] = (Math.floor(Math.random() * 256)) & nn;
      break;

    case 0xD000:
      drawSprite(CHIP8.V[x], CHIP8.V[y], nn, true);
      break;

    case 0xE000:
      if (ins === 0x009E) {
        if (CHIP8.k[CHIP8.V[x] & 0x0F]) CHIP8.pc += 2;
      } else if (ins === 0x00A1) {
        if (!CHIP8.k[CHIP8.V[x] & 0x0F]) CHIP8.pc += 2;
      }
      break;

    case 0xF000:
      switch (nn) {
        case 0x00: CHIP8.V[x] = CHIP8.delayTimer; break;
        case 0x01: CHIP8.delayTimer = CHIP8.V[x]; break;
        case 0x02: CHIP8.soundTimer = CHIP8.V[x]; break;
        case 0x0A: {
          // Wait for key (blocking)
          for (let i = 0; i < 16; i++) {
            if (CHIP8.k[i]) { CHIP8.V[x] = i; break; }
          }
          break;
        }
        case 0x15: CHIP8.I = CHIP8.V[x]; break;
        case 0x18: CHIP8.I = CHIP8.V[x]; break;
        case 0x1E: CHIP8.I = (CHIP8.I + CHIP8.V[x]) & 0xFFFF; break;
        case 0x29: CHIP8.I = 0x50 + ((CHIP8.V[x] & 0x0F) * 5); break;
        case 0x33: {
          const v = CHIP8.V[x];
          mem[CHIP8.I] = Math.floor(v / 100) & 0xFF;
          mem[CHIP8.I + 1] = Math.floor((v % 100) / 10) & 0xFF;
