/* ---------- 60 Hz timer tick ---------- */

function tickTimers() {
  if (CHIP8.delayTimer > 0) CHIP8.delayTimer--;
  if (CHIP8.soundTimer > 0) CHIP8.soundTimer--;
}

/* ---------- Render ---------- */

function render() {
  const data = img.data;
  for (let i = 0; i < 64 * 32; i++) {
    const on = CHIP8.display[i];
    const o = i * 4;
    data[o] = on ? 255 : 0;
    data[o + 1] = on ? 255 : 0;
    data[o + 2] = on ? 255 : 0;
    data[o + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
}

