  const pressed = [];
  for (let i = 0; i < 16; i++) if (CHIP8.k[i]) pressed.push(i.toString(16).toUpperCase());
  document.getElementById("dbg-keys").textContent = pressed.length ? pressed.join(" ") : "none";

  // current instruction
  const mem = CHIP8.memory;
  const ins = ((mem[CHIP8.pc] << 8) | mem[CHIP8.pc + 1]) & 0xFFFF;
  document.getElementById("dbg-ins-pc").textContent = hex2(CHIP8.pc);
  const d = decode(ins);
  document.getElementById("dbg-ins").textContent = d[0] + (d[1] ? " " + d[1] : "") + "  " + d[2];

